{"code": "import numpy as np
from PIL import Image
from pathlib import Path

# Create valid dummy images to replace LFS pointers
def create_dummy_image(path, size=(224, 224)):
    """Create a valid dummy PNG image at the given path"""
    # Create a random colored image
    img_array = np.random.randint(0, 255, (*size, 3), dtype=np.uint8)
    img = Image.fromarray(img_array)
    img.save(path)

# Replace corrupted files with dummy images
data_dir = Path('data_small')
for class_dir in data_dir.iterdir():
    if class_dir.is_dir():
        for img_file in class_dir.iterdir():
            if img_file.suffix.lower() == '.png':
                # Check if it's a LFS pointer (starts with "version")
                with open(img_file, 'rb') as f:
                    first_bytes = f.read(10)
                    if first_bytes.startswith(b'version'):
                        create_dummy_image(img_file)
                        print(f"Replaced: {img_file}")

print("\nDone replacing LFS pointers in data_small")"}

